function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must have the same length.';
  if (operations.length < 1 || operations[0] !== 'Robot') return 'The first operation must be "Robot".';
  if (operations.length > 10001) return 'At most 10^4 calls follow the constructor.';
  const [width, height] = args[0] ?? [];
  if (!Number.isInteger(width) || !Number.isInteger(height) || width < 2 || width > 100 || height < 2 || height > 100) return 'width and height are between 2 and 100.';
  for (let i = 1; i < operations.length; i++) {
    const op = operations[i];
    if (op === 'step') {
      const num = args[i]?.[0];
      if (!Number.isInteger(num) || num < 1 || num > 100000) return 'step takes num between 1 and 10^5.';
    } else if (op !== 'getPos' && op !== 'getDir') return 'Only step, getPos and getDir may follow the constructor.';
  }
  return null;
}

