class Robot {
  constructor(width, height) {
    this.right = width - 1;
    this.top = height - 1;
    this.perimeter = 2 * (this.right + this.top);
    this.index = 0;
    this.moved = false;
  }

  step(num) {
    this.moved = true;
    this.index = (this.index + num) % this.perimeter;
  }

  locate() {
    const { right, top, index } = this;
    if (index === 0) return [0, 0, this.moved ? 'South' : 'East'];
    if (index <= right) return [index, 0, 'East'];
    if (index <= right + top) return [right, index - right, 'North'];
    if (index <= 2 * right + top) return [right - (index - right - top), top, 'West'];
    return [0, top - (index - 2 * right - top), 'South'];
  }

  getPos() {
    const [x, y] = this.locate();
    return [x, y];
  }

  getDir() {
    return this.locate()[2];
  }
}

