class Robot {
  constructor(width, height) {
    this.w = width;
    this.h = height;
    this.x = 0;
    this.y = 0;
    this.d = 0;
  }
  step(num) {
    const dx = [1, 0, -1, 0], dy = [0, 1, 0, -1];
    for (let s = 0; s < num; s++) {
      for (;;) {
        const nx = this.x + dx[this.d], ny = this.y + dy[this.d];
        if (nx >= 0 && nx < this.w && ny >= 0 && ny < this.h) { this.x = nx; this.y = ny; break; }
        this.d = (this.d + 1) % 4;
      }
    }
  }
  getPos() { return [this.x, this.y]; }
  getDir() { return ['East', 'North', 'West', 'South'][this.d]; }
}

