function generate(rand, size) {
  const large = size === 'large';
  const width = large ? 2 + Math.floor(rand() * 99) : 2 + Math.floor(rand() * 4);
  const height = large ? 2 + Math.floor(rand() * 99) : 2 + Math.floor(rand() * 4);
  const perimeter = 2 * (width - 1) + 2 * (height - 1);
  const count = large ? 499 : 1 + Math.floor(rand() * 14);
  const operations = ['Robot'];
  const args = [[width, height]];
  for (let i = 0; i < count; i++) {
    const pick = rand();
    if (pick < 0.5) {
      operations.push('step');
      let num;
      if (large) num = 1 + Math.floor(rand() * 100000);
      else if (rand() < 0.25) num = perimeter * (1 + Math.floor(rand() * 2));
      else num = 1 + Math.floor(rand() * (perimeter + 3));
      args.push([num]);
    } else {
      operations.push(pick < 0.75 ? 'getPos' : 'getDir');
      args.push([]);
    }
  }
  return [operations, args];
}
